import { WebPlugin } from '@capacitor/core';

import type { HyperServicesPlugin } from './definitions';

declare global {
  interface Window {
    HyperServices: any;
  }
}
export class HyperServicesWeb extends WebPlugin implements HyperServicesPlugin {
  hyperServices: any;

  async createHyperServices(options?: {
    clientId?: string;
    service?: string;
  }): Promise<void> {
    return this.createHyperServicesInternal(
      options?.clientId,
      undefined,
      options?.service,
    );
  }

  async createHyperServicesWithTenantId(options: {
    tenantId: string;
    clientId?: string;
    service?: string;
    env?: string;
  }): Promise<void> {
    return this.createHyperServicesInternal(
      options.clientId,
      options.tenantId,
      options.service,
      options.env,
    );
  }

  private createHyperServicesInternal(
    clientId?: string,
    tenantId?: string,
    service?: string,
    env?: string,
  ): Promise<void> {
    return new Promise(resolve => {
      const jsElm = document.createElement('script');
      const baseSDKUrl = this.getSDKBaseDomain(tenantId, env);
      jsElm.type = 'application/javascript';
      jsElm.src = baseSDKUrl + '/HyperServices.js';
      if (service) {
        jsElm.setAttribute('service', service);
      }
      if (clientId) {
        jsElm.setAttribute('clientId', clientId);
      }
      document.body.appendChild(jsElm);
      const self = this;
      jsElm.onload = function () {
        self.hyperServices = new window.HyperServices();
        resolve();
      };
    });
  }

  private getSDKBaseDomain(tenantId = '', env?: string) {
    switch (tenantId) {
      case 'juspayglobal':
      case 'jp_global':
        return env == 'sandbox'
          ? 'https://payments.sandbox.juspay.io/payment-page'
          : 'https://payments.juspay.io/payment-page';
      default:
        return 'https://public.releases.juspay.in/hyper-sdk-web';
    }
  }

  async preFetch(payload: any): Promise<void> {
    return new Promise(resolve => {
      window.HyperServices.preFetch(payload);
      resolve();
    });
  }

  async initiate(payload: any): Promise<void> {
    return new Promise((resolve, reject) => {
      if (!this.hyperServices) {
        reject(new Error('HyperServices instance not created'));
        return;
      }
      this.hyperServices.initiate(payload, (responseData: any) => {
        try {
          this.notifyListeners('HyperEvent', responseData);
        } catch (error) {
          //Error handling
          reject(new Error('' + error));
        }
      });
      resolve();
    });
  }

  async process(payload: any): Promise<void> {
    return new Promise((resolve, reject) => {
      if (!this.hyperServices) {
        reject(new Error('HyperServices instance not created'));
        return;
      }
      // Payment Widget: resolve div ID string to actual DOM element
      if (
        payload?.payload?.fragmentViewGroups?.paymentWidget &&
        typeof payload.payload.fragmentViewGroups.paymentWidget === 'string'
      ) {
        const divElement = document.getElementById(
          payload.payload.fragmentViewGroups.paymentWidget,
        );
        if (divElement) {
          payload.payload.fragmentViewGroups.paymentWidget = divElement;
        }
      }
      this.hyperServices.process(payload);
      resolve();
    });
  }

  async terminate(): Promise<void> {
    return new Promise((resolve, reject) => {
      if (!this.hyperServices) {
        reject(
          new Error(
            'HyperServices instance not created or already terminated!',
          ),
        );
        return;
      }
      this.hyperServices.terminate();
      this.hyperServices = null;
      resolve();
    });
  }

  async isInitialised(): Promise<{ isInitialised: boolean }> {
    return new Promise(resolve => {
      resolve({ isInitialised: this.hyperServices.isInitialised() });
    });
  }

  async onBackPressed(): Promise<{ onBackPressed: boolean }> {
    return new Promise(resolve => {
      resolve({ onBackPressed: this.hyperServices.handleBackpress() });
    });
  }

  async isNull(): Promise<{ isNull: boolean }> {
    return new Promise(resolve => {
      resolve({ isNull: this.hyperServices == null });
    });
  }
}

